public class JITBenchmark {
    public static int accumulate(int[] data) {
        int sum = 0;
        // The backedge counter tracks this loop. Once it exceeds CompileThreshold,
        // the JIT compiler optimizes the loop body, potentially vectorizing instructions.
        for (int i = 0; i < data.length; i++) {
            sum += data[i];
        }
        return sum;
    }

    public static void main(String[] args) {
        int[] array = new int[1000];
        for (int i = 0; i < 20000; i++) {
            accumulate(array); // Warmed up, transitions through Tiers 0 -> 3 -> 4
        }
    }
}
